import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor sigmoid_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ __launch_bounds__(256) void sigmoid_kernel(const float* __restrict__ X,
                                float* __restrict__ Y,
                                int64_t N)
{
    constexpr int VecSize = 4;
    int64_t idx    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)gridDim.x * blockDim.x;

    int64_t vecN = N / VecSize;

    // Direct vectorized global memory access (bypass CuTe tensor indirection
    // to reduce per-element overhead / register pressure).
    const float4* __restrict__ X4 = reinterpret_cast<const float4*>(X);
    float4* __restrict__ Y4 = reinterpret_cast<float4*>(Y);
    // Manually unrolled (4x) vectorized global memory access to increase
    // memory-level parallelism (more in-flight loads/stores per thread)
    // and amortize loop-overhead, while keeping the same coalesced
    // float4 access pattern and grid-stride coverage.
    int64_t i = idx;
    int64_t stride4 = stride * 4;
    for (; i + 3 * stride < vecN; i += stride4) {
        float4 v0 = __ldg(&X4[i]);
        float4 v1 = __ldg(&X4[i + stride]);
        float4 v2 = __ldg(&X4[i + 2 * stride]);
        float4 v3 = __ldg(&X4[i + 3 * stride]);
        v0.x = __fdividef(1.0f, 1.0f + __expf(-v0.x));
        v0.y = __fdividef(1.0f, 1.0f + __expf(-v0.y));
        v0.z = __fdividef(1.0f, 1.0f + __expf(-v0.z));
        v0.w = __fdividef(1.0f, 1.0f + __expf(-v0.w));
        v1.x = __fdividef(1.0f, 1.0f + __expf(-v1.x));
        v1.y = __fdividef(1.0f, 1.0f + __expf(-v1.y));
        v1.z = __fdividef(1.0f, 1.0f + __expf(-v1.z));
        v1.w = __fdividef(1.0f, 1.0f + __expf(-v1.w));
        v2.x = __fdividef(1.0f, 1.0f + __expf(-v2.x));
        v2.y = __fdividef(1.0f, 1.0f + __expf(-v2.y));
        v2.z = __fdividef(1.0f, 1.0f + __expf(-v2.z));
        v2.w = __fdividef(1.0f, 1.0f + __expf(-v2.w));
        v3.x = __fdividef(1.0f, 1.0f + __expf(-v3.x));
        v3.y = __fdividef(1.0f, 1.0f + __expf(-v3.y));
        v3.z = __fdividef(1.0f, 1.0f + __expf(-v3.z));
        v3.w = __fdividef(1.0f, 1.0f + __expf(-v3.w));
        Y4[i] = v0;
        Y4[i + stride] = v1;
        Y4[i + 2 * stride] = v2;
        Y4[i + 3 * stride] = v3;
    }
    // Handle remaining float4 elements that don't fill a full unrolled group
    for (; i < vecN; i += stride) {
        float4 v = __ldg(&X4[i]);
        v.x = __fdividef(1.0f, 1.0f + __expf(-v.x));
        v.y = __fdividef(1.0f, 1.0f + __expf(-v.y));
        v.z = __fdividef(1.0f, 1.0f + __expf(-v.z));
        v.w = __fdividef(1.0f, 1.0f + __expf(-v.w));
        Y4[i] = v;
    }
    // Handle remainder elements (if N is not divisible by VecSize)
    int64_t rem_start = vecN * VecSize;
    int64_t remN = N - rem_start;
    if (remN > 0) {
        for (int64_t i = idx; i < remN; i += stride) {
            float x = __ldg(&X[rem_start + i]);
            Y[rem_start + i] = __fdividef(1.0f, 1.0f + __expf(-x));
        }
    }
}

torch::Tensor sigmoid_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

    auto x_c = x.contiguous();
    auto y   = torch::empty_like(x_c);

    int64_t N = x_c.numel();

    const int threads = 256;
    int64_t vecN = N / 4;
    int64_t work_units = vecN > 0 ? vecN : N;
    int64_t blocks64 = (work_units + threads - 1) / threads;
    if (blocks64 < 1) blocks64 = 1;
    // Cap grid size to a multiple of the SM count so the grid-stride loop
    // covers the full workload without launching an excessively large
    // number of blocks (which increases scheduling overhead without
    // improving throughput once enough blocks exist to saturate the GPU).
    int device = -1;
    cudaGetDevice(&device);
    int sm_count = 0;
    cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, device);
    if (sm_count <= 0) sm_count = 108; // fallback if query fails
    int64_t max_blocks = (int64_t)sm_count * 32;
    if (blocks64 > max_blocks) blocks64 = max_blocks;
    if (blocks64 > 2147483647LL) blocks64 = 2147483647LL;
    int blocks = (int)blocks64;

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    sigmoid_kernel<<<blocks, threads, 0, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        N
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "sigmoid_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

sigmoid_ext = load_inline(
    name="cute_sigmoid_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["sigmoid_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Sigmoid activation using a custom CUTE/CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = sigmoid_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.sigmoid_forward(x)

